<script lang="ts">
 import {getContext,onMount} from 'svelte';
 import type {I18nState} from '../../../../../lib/i18n/i18n.svelte';
 import type {WarehouseSelectionState} from '../../../warehouses/ui/state/warehouseSelectionState.svelte';
 import {createAuthGuardState} from '../../../auth/ui/state/authGuardState.svelte';
 import {createDashboardState} from '../state/dashboardState.svelte';
 import type {DashboardEvent,DashboardRangeKey} from '../../domain/entity/Dashboard';
 import {dashboardRangeForPreset} from '../../domain/entity/DashboardDateRange';
 const i18n=getContext<I18nState>('i18n'),warehouse=getContext<WarehouseSelectionState>('warehouseSelection'),auth=getContext<ReturnType<typeof createAuthGuardState>>('authGuard'),vm=createDashboardState();
 let showSettings=$state(false);
 const labels:Record<DashboardEvent,{title:string;unit:string}>={picking:{title:'Picking',unit:'orders'},packing:{title:'Packing',unit:'units'},shipped:{title:'Shipped',unit:'orders'},received_skus:{title:'Received',unit:'unique SKUs'},putaway_skus:{title:'Put Away',unit:'unique SKUs'}};
 const isAdmin=$derived(auth.user?.role==='ADMIN'),canSalesOrders=$derived(isAdmin||(auth.user?.allowedPages??[]).includes('sales-orders')),canMarkPickup=$derived(isAdmin||(auth.user?.allowedOverrides??[]).includes('so-full-edit'));
 const presets:{key:DashboardRangeKey;label:string}[]=[{key:'today',label:'Today'},{key:'yesterday',label:'Yesterday'},{key:'last_7d',label:'Last 7d'},{key:'last_30d',label:'Last 30d'},{key:'custom',label:'Custom'}];
 function range(){return dashboardRangeForPreset(vm.rangeKey,vm.customStart,vm.customEnd);}
 function refresh(){const w=warehouse.warehouseId,r=range();if(!w||!r)return;void vm.loadTab(w,r);}
 function setRange(v:DashboardRangeKey){vm.rangeKey=v;refresh();}
 function reorder(slug:DashboardEvent,dir:number){const a=[...vm.preferences.chartOrder],i=a.indexOf(slug),j=i+dir;if(i<0||j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];void vm.updatePreferences({chartOrder:a});}
 function csv(){const p=vm.productivity;if(!p)return;const events=p.eventsVisible,rows=[['User',...events.map(s=>labels[s]?.title??s),'Total']];for(const u of p.users)rows.push([u.displayName||u.username,...events.map(s=>String(u.metrics[s]??0)),String(u.total??0)]);const quote=(v:string)=>'"'+v.replace(/"/g,'""')+'"';const blob=new Blob([rows.map(row=>row.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='productivity-'+p.range.start+'_'+p.range.end+'.csv';a.click();URL.revokeObjectURL(url);}
 function moveTo(slug:DashboardEvent){vm.focusedSource=vm.focusedSource===slug?null:slug;}
 async function doPickup(){if(vm.confirmPickup==null)return;const id=vm.confirmPickup;if(await vm.markPickup(id))refresh();}
 onMount(()=>{if(!isAdmin)vm.activeTab='received';void vm.loadPreferences();});
 $effect(()=>{const id=warehouse.warehouseId,tab=vm.activeTab,key=vm.rangeKey,start=vm.customStart,end=vm.customEnd;if(tab==='pickup')void vm.status;if(id){const r=dashboardRangeForPreset(key,start,end);if(r)void vm.loadTab(id,r);}});
</script>
<svelte:head><title>Dashboard · Smart WMS</title></svelte:head>
<section class="page">
 <header class="page-head"><div><p class="eyebrow">ABELLIS · SMART WMS</p><h1>{i18n.t('Dashboard')}</h1><p>{i18n.t('Productividad, recepción, envíos y recogida local.')}</p></div><button class="secondary" onclick={refresh} disabled={vm.loading}>{vm.loading?i18n.t('Cargando…'):i18n.t('Actualizar')}</button></header>
 <nav class="tabs" aria-label="Dashboard views">
  {#if isAdmin}<button class:active={vm.activeTab==='productivity'} onclick={()=>vm.activeTab='productivity'}>Productivity</button>{/if}
  <button class:active={vm.activeTab==='received'} onclick={()=>vm.activeTab='received'}>Received</button>
  <button class:active={vm.activeTab==='shipping'} onclick={()=>vm.activeTab='shipping'}>Marketplace Health</button>
  {#if canSalesOrders}<button class:active={vm.activeTab==='pickup'} onclick={()=>vm.activeTab='pickup'}>Local Pickup</button>{/if}
 </nav>
 {#if vm.activeTab!=='pickup'}
 <div class="toolbar">
  <div class="ranges">{#each presets as p}<button class:active={vm.rangeKey===p.key} onclick={()=>setRange(p.key)}>{p.label}</button>{/each}</div>
  {#if vm.rangeKey==='custom'}<label class="date">{i18n.t('Desde')}<input type="date" bind:value={vm.customStart} onchange={refresh}/></label><label class="date">{i18n.t('Hasta')}<input type="date" bind:value={vm.customEnd} onchange={refresh}/></label>{/if}
  {#if vm.activeTab==='productivity'}<div class="view-toggle"><button class:active={vm.view==='charts'} onclick={()=>vm.view='charts'}>Charts</button><button class:active={vm.view==='table'} onclick={()=>vm.view='table'}>Table</button>{#if vm.view==='table'}<button onclick={csv} disabled={!vm.productivity}>Export CSV</button>{/if}<button onclick={()=>showSettings=true} aria-label="Dashboard settings">⚙</button></div>{/if}
 </div>
 {/if}
 {#if vm.error}<p class="error" role="alert">{vm.error}</p>{/if}
 {#if vm.loading}<div class="loading" aria-live="polite">{i18n.t('Cargando datos…')}</div>{/if}
 {#if vm.activeTab==='productivity'}
  {#if !isAdmin}<p class="notice">Productivity is available to administrators only.</p>
  {:else if vm.productivity}
   {#if vm.productivity.warnings.length}<div class="notice">{#each vm.productivity.warnings as warning}<p>{warning}</p>{/each}</div>{/if}
   {#if vm.view==='table'}
    <div class="table-wrap"><table><thead><tr><th>User</th>{#each vm.productivity.eventsVisible as e}<th>{labels[e]?.title??e}</th>{/each}<th>Total</th></tr></thead><tbody>{#each vm.productivity.users as u (u.userId)}<tr><td>{u.displayName||u.username}</td>{#each vm.productivity.eventsVisible as e}<td class="num">{u.metrics[e]??0}</td>{/each}<td class="num strong">{u.total}</td></tr>{/each}{#if !vm.productivity.users.length}<tr><td colspan={vm.productivity.eventsVisible.length+2} class="empty">No data for this range.</td></tr>{/if}</tbody></table></div>
   {:else}
    <div class="chart-grid">{#each vm.preferences.chartOrder.filter(s=>vm.productivity?.eventsVisible.includes(s)) as slug}<button class="metric-card" onclick={()=>moveTo(slug)}><div class="metric-head"><strong>{labels[slug]?.title??slug}</strong><b>{vm.productivity?.totalsPerEvent[slug]??0}</b></div><small>{labels[slug]?.unit??''}</small>{#if vm.focusedSource===slug}<div class="bars">{#each [...vm.productivity.users].filter(u=>(u.metrics[slug]??0)>0).sort((a,b)=>(b.metrics[slug]??0)-(a.metrics[slug]??0)) as u,i}<div class="bar-row"><span>{u.displayName||u.username}</span><div class="track"><i style={'width:'+Math.max(2,((u.metrics[slug]??0)/Math.max(1,...vm.productivity.users.map(x=>x.metrics[slug]??0)))*100)+'%'}></i></div><b>{u.metrics[slug]??0}</b></div>{/each}{#if !vm.productivity.users.some(u=>(u.metrics[slug]??0)>0)}<p class="empty">No data for this range.</p>{/if}</div>{:else}<p class="hint">Open breakdown ↗</p>{/if}</button>{/each}</div>
   {/if}
  {/if}
 {:else if vm.activeTab==='received'&&vm.received}
  {@const rows=vm.received.pos}
  <div class="summary"><span><b>{rows.length}</b> POs received</span><span><b>{rows.reduce((a,x)=>a+x.linesReceived,0)}</b> lines</span><span><b>{rows.reduce((a,x)=>a+x.unitsReceived,0)}</b> units</span><span><b>{new Set(rows.flatMap(x=>x.receivers)).size}</b> receivers active</span></div>
  {#if !rows.length}<p class="empty">No POs received units in this range.</p>{:else}<div class="table-wrap"><table><thead><tr><th>PO #</th><th>Vendor</th><th>Status</th><th>Lines</th><th>Units</th><th>Receiver(s)</th><th>Last received</th></tr></thead><tbody>{#each rows as r (r.poId)}<tr><td>{r.poNumber}</td><td>{r.vendorName??'—'}</td><td>{r.status}</td><td class="num">{r.linesReceived}</td><td class="num">{r.unitsReceived}</td><td>{r.receivers.join(', ')||'—'}</td><td>{r.lastReceivedAt?new Date(r.lastReceivedAt).toLocaleString():'—'}</td></tr>{/each}</tbody></table></div>{/if}
 {:else if vm.activeTab==='shipping'&&vm.shipping}
  {#if !vm.shipping.bySource.length}<p class="empty">No marketplace channels are configured. Add one under Settings → Marketplace Health.</p>{:else}
   <h2>Marketplace Breakdown</h2><div class="channel-grid">{#each vm.shipping.bySource as row (row.orderOrigin)}<article class="channel-card"><h3>{row.label}</h3><div class="two-stats"><div><b>{row.ordersReceived}</b><small>Orders Received</small></div><div><b>{row.ordersShipped}</b><small>Orders Shipped</small></div></div><button class:attention={row.needToShipToday>0} class="pickup-bubble" onclick={()=>vm.focusedSource=row.orderOrigin}><span>{row.label}</span><strong>{row.needToShipToday||'✓'}</strong><small>Need to ship today</small></button></article>{/each}</div>
   {#if vm.focusedSource}<div class="modal-backdrop" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget)vm.focusedSource=null}}><section class="modal" role="dialog" aria-modal="true" aria-label="Orders needing shipment"><header><h2>{vm.shipping.bySource.find(x=>x.orderOrigin===vm.focusedSource)?.label} — orders to ship</h2><button onclick={()=>vm.focusedSource=null}>Close</button></header>{@const selected=vm.shipping.bySource.find(x=>x.orderOrigin===vm.focusedSource)}{#if !selected?.orders.length}<p class="empty">No orders to show.</p>{:else}<div class="table-wrap"><table><thead><tr><th>SO #</th><th>Customer</th><th>Status</th><th>Ship by</th></tr></thead><tbody>{#each selected.orders as o (o.soId)}<tr><td>{o.soNumber}</td><td>{o.customerName??'—'}</td><td>{o.status}</td><td>{o.shipByDate??'—'}</td></tr>{/each}</tbody></table></div>{/if}</section></div>{/if}
  {/if}
 {:else if vm.activeTab==='pickup'}
  {#if !canSalesOrders}<p class="notice">You do not have access to sales orders.</p>{:else}
   <div class="pickup-tools"><input placeholder="Search by customer or order #" bind:value={vm.search}/><select bind:value={vm.status}><option value="All">All statuses</option><option value="OPEN,PICKED">Open + Picked</option>{#each ['OPEN','PICKED','PACKED','SHIPPED','CANCELLED'] as s}<option value={s}>{s}</option>{/each}</select><button class="secondary" onclick={refresh}>Search / Refresh</button><span>{vm.pickup.orders.length} / {vm.pickup.total} orders</span></div>
   {#if !vm.pickup.orders.length&&!vm.loading}<p class="empty">No local pickup orders match.</p>{:else}<div class="table-wrap"><table><thead><tr><th>Order #</th><th>Customer</th><th>Status</th><th>Order Date</th><th>Actions</th></tr></thead><tbody>{#each vm.pickup.orders as o (o.soId)}<tr><td>{o.soNumber}</td><td>{o.customerName??'—'}</td><td>{o.status}</td><td>{o.orderDate??o.createdAt??'—'}</td><td>{#if o.status==='SHIPPED'}<span class="success">Picked up ✓</span>{:else}<button class="danger" disabled={!canMarkPickup||!['PICKED','PACKED'].includes(o.status)||vm.pickupBusy} title={!canMarkPickup?'Requires ADMIN or so-full-edit':!['PICKED','PACKED'].includes(o.status)?'Order must be PICKED or PACKED':''} onclick={()=>vm.confirmPickup=o.soId}>Picked Up?</button>{/if}</td></tr>{/each}</tbody></table></div>{/if}
  {/if}
 {/if}
</section>
{#if showSettings}<div class="modal-backdrop" role="presentation" onclick={e=>{if(e.target===e.currentTarget)showSettings=false}}><section class="modal" role="dialog" aria-modal="true"><header><h2>Dashboard settings</h2><button onclick={()=>showSettings=false}>Close</button></header><p>Per-user preferences. {vm.saving?'Saving…':'Saves on every change.'}</p><label>Default range<select value={vm.preferences.defaultRange} onchange={e=>void vm.updatePreferences({defaultRange:e.currentTarget.value as DashboardRangeKey})}>{#each presets as p}<option value={p.key}>{p.label}</option>{/each}</select></label><label>Default view<select value={vm.preferences.defaultView} onchange={e=>void vm.updatePreferences({defaultView:e.currentTarget.value as 'charts'|'table'})}><option value="charts">Charts</option><option value="table">Table</option></select></label><h3>Chart order</h3>{#each vm.preferences.chartOrder as slug,i}<div class="order-row"><span>{labels[slug]?.title??slug}</span><button disabled={i===0} onclick={()=>reorder(slug,-1)}>↑</button><button disabled={i===vm.preferences.chartOrder.length-1} onclick={()=>reorder(slug,1)}>↓</button></div>{/each}</section></div>{/if}
{#if vm.confirmPickup!=null}<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><h2>Mark picked up?</h2><p>This marks the order as SHIPPED and records the customer handoff. It cannot be undone from this worklist.</p>{#if !canMarkPickup}<p class="error">Requires ADMIN or the so-full-edit override.</p>{/if}<footer><button class="secondary" disabled={vm.pickupBusy} onclick={()=>vm.confirmPickup=null}>Cancel</button><button class="danger" disabled={!canMarkPickup||vm.pickupBusy} onclick={()=>void doPickup()}>{vm.pickupBusy?'Working…':'Yes, mark picked up'}</button></footer></section></div>{/if}
<style>
.page{max-width:90rem;margin:1.3rem auto;padding:0 1.2rem;color:var(--ink)}.page-head{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:1.1rem}.eyebrow{font-size:.67rem;font-weight:700;letter-spacing:.13em;color:var(--slate)}h1{margin:.1rem 0;font:700 1.7rem var(--disp)}.page-head p:last-child{margin:.3rem 0;color:var(--slate);font-size:.9rem}.tabs,.ranges,.view-toggle{display:flex;flex-wrap:wrap;gap:.35rem}.tabs{border-bottom:1px solid var(--line);margin-bottom:1rem}.tabs button,.ranges button,.view-toggle button,.secondary{border:1px solid var(--line);border-radius:8px;padding:.5rem .75rem;background:var(--surface);color:var(--ink);cursor:pointer}.tabs button{border:0;border-bottom:2px solid transparent;border-radius:0}.tabs button.active,.ranges button.active,.view-toggle button.active{background:var(--surface-2);border-color:var(--navy);font-weight:700}.toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:.65rem;margin-bottom:1rem}.view-toggle{margin-left:auto}.date{display:grid;gap:.2rem;font-size:.72rem;color:var(--slate)}input,select{min-height:36px;border:1px solid var(--line);border-radius:7px;padding:.4rem .55rem;background:var(--surface);color:var(--ink)}.chart-grid,.channel-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:.85rem}.metric-card,.channel-card{border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:1rem;color:var(--ink);text-align:left}.metric-card{cursor:pointer;min-height:170px}.metric-head{display:flex;justify-content:space-between;align-items:center}.metric-head b{font:700 1.6rem var(--mono,monospace)}.metric-card>small,.hint,.channel-card small{color:var(--slate);font-size:.75rem}.hint{margin-top:2rem}.bars{display:grid;gap:.45rem;margin-top:1rem}.bar-row{display:grid;grid-template-columns:6rem 1fr 2rem;align-items:center;gap:.45rem;font-size:.72rem}.bar-row span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.track{height:10px;border-radius:5px;background:var(--surface-2);overflow:hidden}.track i{display:block;height:100%;background:var(--navy);border-radius:5px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:11px;background:var(--surface)}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:.8rem}th,td{padding:.65rem .75rem;border-bottom:1px solid var(--line);text-align:left}th{font-size:.68rem;text-transform:uppercase;color:var(--slate)}.num{text-align:right;font-variant-numeric:tabular-nums}.strong{font-weight:700}.empty,.loading{padding:1.5rem;color:var(--slate);font-size:.85rem}.summary{display:flex;flex-wrap:wrap;gap:1.2rem;margin:.8rem 0 1rem;color:var(--slate);font-size:.82rem}.summary b{color:var(--ink)}.channel-card h3{text-align:center}.two-stats{display:grid;grid-template-columns:1fr 1fr;text-align:center;border-top:1px solid var(--line);padding:.7rem}.two-stats div{display:grid;gap:.2rem}.two-stats b{font:700 1.5rem var(--mono,monospace)}.pickup-bubble{width:100%;display:grid;gap:.4rem;justify-items:center;padding:1rem;border:1px solid var(--line);border-radius:12px;background:var(--surface-2);color:var(--ink);cursor:pointer}.pickup-bubble strong{font:700 2.3rem var(--mono,monospace)}.pickup-bubble.attention{border:2px solid var(--accent)}.pickup-tools{display:flex;flex-wrap:wrap;align-items:center;gap:.6rem;margin-bottom:1rem}.pickup-tools input{min-width:15rem}.pickup-tools span{margin-left:auto;color:var(--slate);font-size:.8rem}.danger{border:1px solid var(--accent);border-radius:7px;background:var(--accent);color:white;padding:.45rem .65rem;cursor:pointer}.danger:disabled{opacity:.45;cursor:not-allowed}.success{color:#23864a;font-weight:700}.notice{padding:1rem;border:1px solid var(--line);border-radius:10px;color:var(--slate)}.error{color:var(--danger)}.modal-backdrop{position:fixed;inset:0;z-index:120;background:#0008;display:grid;place-items:center;padding:1rem}.modal{width:min(52rem,96vw);max-height:85vh;overflow:auto;padding:1.2rem;border:1px solid var(--line);border-radius:14px;background:var(--surface);color:var(--ink);box-shadow:var(--shadow-2)}.modal header,.modal footer{display:flex;justify-content:space-between;align-items:center;gap:.6rem}.modal label{display:grid;gap:.35rem;margin:.8rem 0;font-size:.82rem}.order-row{display:flex;align-items:center;gap:.4rem;padding:.45rem;border-bottom:1px solid var(--line)}.order-row span{flex:1}.order-row button,.modal header button{border:1px solid var(--line);border-radius:7px;background:var(--surface-2);color:var(--ink);padding:.35rem .55rem}.modal footer{justify-content:flex-end;margin-top:1rem}@media(max-width:650px){.page-head{align-items:flex-start;flex-direction:column}.view-toggle{margin-left:0}.pickup-tools input{min-width:100%;width:100%}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
</style>